const raw = $input.first().json;
let task;
try { task = typeof raw.task === 'string' ? JSON.parse(raw.task) : raw.task; }
catch (e) { throw new Error('task is not valid JSON'); }
if (!task || typeof task !== 'object') throw new Error('task is missing');
for (const k of ['task_id', 'agent', 'goal']) {
  if (!task[k]) throw new Error('task missing ' + k);
}
task.mode = 'propose';          // this workflow can never run in another mode
task.inputs = task.inputs || {};
return [{ json: { user_id: raw.user_id, task } }];

const profile = $('Load profile').first().json;
const { task } = $('Parse task').first().json;
const j = (v, fallback) => {            // Data table JSON columns arrive as text
  try { return typeof v === 'string' ? JSON.parse(v) : (v ?? fallback); } catch (e) { return fallback; }
};
const tz = profile.tz || 'Asia/Kolkata';
const prefs = j(profile.preferences, {});
return [{ json: {
  task,
  ctx: {
    user_id: profile.user_id, user_name: profile.name, user_email: profile.email,
    tz, now: DateTime.now().setZone(tz).toISO(),
    working_hours: j(profile.working_hours, { start: '09:30', end: '18:30' }),
    calendars: j(profile.calendars, []), preferences: prefs,
    default_duration: prefs.default_duration || 30,
    buffer_minutes: prefs.buffer_minutes || 10,
    company_domains: prefs.company_domains || ['example.com'],   // replace with yours
    vip: prefs.vip || [], standing_approvals: j(profile.standing_approvals, [])
  }
} }];

